#!/usr/bin/env bash
# Generated by testing/render-graders.sh from validate.sh. Do not edit by hand.
# Grades the outcome kubelet-config-hardened and prints one PASS: or FAIL: line.
# Runs on the lab VM as the astrona account (astrona pipes it into bash).

# >>> shared checks >>>
LAB_NAME=ats-032-lab-030-01-02
LAB_CONTEXT="kubernetes-admin@astro-$LAB_NAME"
NODE=controlplane
NAMESPACE=starfleet-032-030-01-02
OUTCOMES="kubelet-config-hardened kubelet-anon-rejected node-ready"

kube() {
  sudo -n kubectl --kubeconfig /etc/kubernetes/admin.conf --request-timeout=15s "$@" </dev/null
}

# Context guard: the graders only read this VM's own cluster.
lab_guard() {
  local context
  if [ ! -r /etc/kubernetes/admin.conf ] && ! sudo -n test -r /etc/kubernetes/admin.conf; then
    echo "FAIL: guard: /etc/kubernetes/admin.conf is missing, so this is not the lab VM or kubeadm init did not run"
    return 1
  fi
  context=$(kube config current-context 2>/dev/null) || context=""
  if [ "$context" != "$LAB_CONTEXT" ]; then
    echo "FAIL: guard: admin.conf context is '$context', expected '$LAB_CONTEXT'"
    return 1
  fi
}

# The configuration the running kubelet uses, read through the API server.
kubelet_settings() {
  kube get --raw "/api/v1/nodes/$NODE/proxy/configz" 2>/dev/null | jq -c '.kubeletconfig' 2>/dev/null
}

# Prints the first hardening setting that is still wrong, or nothing.
kubelet_problem() {
  local settings="$1"
  if [ -z "$settings" ] || [ "$settings" = "null" ]; then
    echo "the API server cannot read the configuration of the kubelet on $NODE; is the kubelet running?"
  elif [ "$(jq -r '.authentication.anonymous.enabled' <<<"$settings")" != "false" ]; then
    echo "the kubelet on $NODE still accepts anonymous requests (authentication.anonymous.enabled)"
  elif [ "$(jq -r '.authentication.webhook.enabled' <<<"$settings")" != "true" ]; then
    echo "keep webhook token authentication on (authentication.webhook.enabled: true)"
  elif [ "$(jq -r '.authorization.mode' <<<"$settings")" != "Webhook" ]; then
    echo "the kubelet on $NODE uses authorization mode '$(jq -r '.authorization.mode' <<<"$settings")', expected Webhook"
  elif [ "$(jq -r '.readOnlyPort // 0' <<<"$settings")" != "0" ]; then
    echo "the read-only port of the kubelet on $NODE is $(jq -r '.readOnlyPort' <<<"$settings"), expected 0"
  fi
}

node_address() {
  kube get node "$NODE" -o jsonpath='{.status.addresses[?(@.type=="InternalIP")].address}' 2>/dev/null
}

check_kubelet_config_hardened() {
  local problem
  problem=$(kubelet_problem "$(kubelet_settings)")
  if [ -n "$problem" ]; then
    echo "FAIL: kubelet-config-hardened: $problem"
    return 1
  fi
  echo "PASS: kubelet-config-hardened: the kubelet on $NODE runs with anonymous authentication off, Webhook authorization and readOnlyPort 0"
}

check_kubelet_anon_rejected() {
  local address status code
  address=$(node_address) || address=""
  if [ -z "$address" ]; then
    echo "FAIL: kubelet-anon-rejected: node $NODE has no InternalIP address"
    return 1
  fi
  status=$(curl -sk -m 5 -o /dev/null -w '%{http_code}' "https://$address:10250/pods" 2>/dev/null) || true
  if [ "$status" != "401" ]; then
    echo "FAIL: kubelet-anon-rejected: an anonymous request to https://$address:10250/pods returned ${status:-no answer}, expected 401"
    return 1
  fi
  code=0
  curl -s -m 5 -o /dev/null "http://$address:10255/pods" 2>/dev/null || code=$?
  if [ "$code" != "7" ]; then
    echo "FAIL: kubelet-anon-rejected: port 10255 on $address must refuse connections (curl exit code $code, expected 7)"
    return 1
  fi
  echo "PASS: kubelet-anon-rejected: port 10250 returns 401 to an anonymous request and port 10255 refuses connections"
}

check_node_ready() {
  local ready problem pod_node logs
  ready=$(kube get node "$NODE" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null) || ready=""
  if [ "$ready" != "True" ]; then
    echo "FAIL: node-ready: node $NODE is not Ready"
    return 1
  fi
  problem=$(kubelet_problem "$(kubelet_settings)")
  if [ -n "$problem" ]; then
    echo "FAIL: node-ready: the kubelet is not running with the hardened configuration yet: $problem"
    return 1
  fi
  pod_node=$(kube -n "$NAMESPACE" get pod probe -o jsonpath='{.spec.nodeName}' 2>/dev/null) || pod_node=""
  if [ "$pod_node" != "$NODE" ]; then
    echo "FAIL: node-ready: Pod probe in $NAMESPACE must still run on $NODE"
    return 1
  fi
  logs=$(kube -n "$NAMESPACE" logs probe 2>/dev/null) || logs=""
  if ! grep -q 'probe started' <<<"$logs"; then
    echo "FAIL: node-ready: the API server cannot read the logs of Pod probe through the kubelet"
    return 1
  fi
  echo "PASS: node-ready: node $NODE is Ready with the hardened kubelet, and kubectl logs still works for Pod probe"
}

grade() {
  lab_guard || return 1
  case "$1" in
    kubelet-config-hardened) check_kubelet_config_hardened ;;
    kubelet-anon-rejected) check_kubelet_anon_rejected ;;
    node-ready) check_node_ready ;;
    *) echo "FAIL: Unknown outcome '$1'"; return 1 ;;
  esac
}
# <<< shared checks <<<

main() {
  grade kubelet-config-hardened
}

main
